{
  "probability": 0.83,
  "range_low": 0.75,
  "range_high": 0.9,
  "summary": [
    "Late-February 2026 polls place CDU ahead or narrowly ahead of Greens with small seat margins.",
    "Greens closing the gap in several polls, compressing CDU's edge.",
    "AfD remains a non-negligible factor influencing seat distribution.",
    "Historical context shows Greens led in 2016 and 2021, tempering certainty of a CDU win."
  ],
  "confidence": "high",
  "narrative": "Anchored on late-February 2026 polls showing CDU leading or neck-and-neck with Greens and seat projections favoring CDU by a slim margin, the Bayesian updates yield a posterior probability of 0.83 that CDU wins the most seats. Greens momentum, AfD's persistent support, and the Greens' recent baseline introduce notable but not decisive uncertainty, keeping the race competitive but still favoring CDU as the most probable largest party.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class: Baden-Württemberg Landtag elections with mixed-member proportional representation; late-February 2026 pre-election polls (Infratest dimap, INSA) show CDU ahead or neck-and-neck with Greens; seat projections indicate CDU leading in several models, forming a strong anchor for the probability."
    },
    "factor_updates": [
      {
        "factor": "Late-February 2026 CDU polling momentum",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Infratest dimap Feb 25, 2026 shows CDU 28%, Greens 27%, and seat projections around CDU 37 vs Greens 35, supporting CDU as the likely largest party."
      },
      {
        "factor": "Greens closing the gap in late Feb 2026 polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "INSA and other polls indicate Greens around 22–23% while CDU remains around 28–29%, narrowing the margin and increasing risk of not having a clear CDU majority."
      },
      {
        "factor": "AfD maintaining/raising support in late 2025–early 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "AfD consistently polling in the high teens to low twenties siphons votes that could otherwise bolster CDU’s absolute lead, affecting seat distribution."
      },
      {
        "factor": "Historical baseline: Greens led in 2016 and 2021",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Recent elections show Greens can be the largest party, tempering certainty of a CDU dominance despite current momentum."
      },
      {
        "factor": "Official forecast absence and election context",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "No official forecast; adds uncertainty to anchor but does not override poll-based signals."
      }
    ],
    "synthesis_rationale": "The posterior 0.83 arises from applying these updates to the chosen anchor, accounting for potential correlations (e.g., Greens momentum may correlate with AfD dynamics and turnout effects). The calibration acknowledges that while CDU is favored in the current signal mix, Greens momentum and historical baselines inject downside risk, hence a high-but-not-certainty probability with a broad calibration range."
  }
}

